adas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Recette argentine","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":2,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"c. à c.","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons et le poivron en dés, puis le bœuf et les épices 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Fais durcir un œuf 10 min, hache-le et ajoute-le à la farce.","timer":{"label":"Cuisson","min":10}},{"text":"Préchauffe le four à 200 °C. Découpe des disques de 12 cm dans les pâtes.","timer":null},{"text":"Garnis la moitié de chaque disque, replie et soude les bords à la fourchette.","timer":null},{"text":"Dore au second œuf battu et enfourne 20 min.","timer":{"label":"Four","min":20}}],"makes":{"n":12,"one":"empanada","many":"empanadas"}},{"title":"Feuilletés à la saucisse","intro":"Des petites saucisses roulées dans la pâte feuilletée, pour l'apéritif.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"sausage rolls","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":1,"unit":"","have":false},{"name":"saucisse cocktail","plural":"saucisses cocktail","qty":24,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Tartine la pâte de moutarde et coupe-la en bandes.","timer":null},{"text":"Roule chaque saucisse dans une bande de pâ